@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + birthDate : date
  + website : string
}

class User {
  + ID : int
  + name : string
  + address : string
}

abstract class UserType {}
class RegularUser extends UserType {
  + canBuyMusic : boolean
}
class BusinessUser extends UserType {
  + VATNumber : string
  + canUploadSongs : boolean
}

class Album {
  + title : string
  + trackNumber : int
}

enum SongType { single, hit }

class Musicmatic {
  + suggestAlbumsToUsers(RegularUser) : void
}

Song "1" -- "1" Artist
User "*" -- "0..*" UserType
BusinessUser "0..*" -- "0..*" Song
RegularUser "0..*" -- "0..*" Album
Album "1" -- "0..*" Song

@enduml

